<template><section :aria-label="title"><p class="tool-note">{{note}}</p><div class="tool-actions"><template v-if="mode==='chinese'"><label>转换方向<select v-model="direction" aria-label="简繁转换方向"><option value="cn-tw">简体 → 繁体（台湾字形）</option><option value="tw-cn">繁体 → 简体</option><option value="cn-hk">简体 → 繁体（香港字形）</option><option value="hk-cn">香港繁体 → 简体</option><option value="cn-twp">简体 → 台湾词汇</option><option value="twp-cn">台湾词汇 → 简体</option></select></label></template><template v-if="mode==='pinyin'"><label>声调<select v-model="tone" aria-label="拼音声调"><option value="symbol">声调符号</option><option value="num">数字声调</option><option value="none">无声调</option></select></label><label><input v-model="initials" type="checkbox" />仅首字母</label><label><input v-model="uppercase" type="checkbox" />大写输出</label></template><template v-if="mode==='width'"><label>转换方向<select v-model="widthMode" aria-label="全半角转换方向"><option value="half">转半角</option><option value="full">转全角</option></select></label></template><template v-if="mode==='invisible'"><label><input v-model="includeWhitespace" type="checkbox" />列出换行与制表符</label><label><input v-model="keepWhitespace" type="checkbox" />清理时保留换行制表符</label><label><input v-model="keepEmoji" type="checkbox" />清理时保留表情连接符与变体符</label></template></div><div class="tool-two-column"><label class="tool-label">{{title}}输入<textarea v-model="input" :aria-label="title+'输入'" maxlength="20000" spellcheck="false"></textarea></label><label class="tool-label">{{title}}结果<textarea v-model="output" :aria-label="title+'结果'" readonly spellcheck="false"></textarea></label></div><div class="tool-actions"><button type="button" :disabled="busy" @click="run">{{busy?'处理中…':mode==='invisible'?'检查并标注字符':'开始转换'}}</button><button v-if="mode==='invisible'" type="button" @click="clean">生成清理副本</button><button type="button" :disabled="!output" @click="copy">复制{{title}}结果</button><button type="button" @click="clear">清空{{title}}</button></div><template v-if="mode==='invisible'&&inspection"><p>检测到 {{inspection.total}} 个、{{inspection.kinds}} 种字符。最多列出前 300 处，行列从 1 开始，列按 Unicode 字符计数。</p><div class="invisible-table"><table><thead><tr><th>行:列</th><th>代码点</th><th>名称</th></tr></thead><tbody><tr v-for="row in inspection.rows" :key="row.offset"><td>{{row.line}}:{{row.column}}</td><td>{{row.code}}</td><td>{{row.name}}</td></tr></tbody></table></div></template><p role="status">{{message}}</p></section></template>
<script>
import {convertChinese,chineseToPinyin,convertWidth,inspectInvisible,cleanInvisible} from '../../utils/language-privacy-tools.mjs';
const TITLES={chinese:'简繁体转换',pinyin:'汉字转拼音',width:'全角半角转换',invisible:'不可见字符检查'};
export default {name:'LanguageTool',props:{mode:{type:String,required:true}},data:()=>({input:'',output:'',direction:'cn-tw',tone:'symbol',initials:false,uppercase:false,widthMode:'half',includeWhitespace:false,keepWhitespace:true,keepEmoji:true,inspection:null,message:'',busy:false,request:0}),computed:{title(){return TITLES[this.mode];},note(){return {chinese:'基于 OpenCC 字词转换，可选择地区字形与词汇；人名、专名和语境词请自行核对。单次最多 2 万字符。',pinyin:'使用词典推断多音字，可选择声调、首字母和大写。专名读音可能需要人工核对。单次最多 2 万字符。',width:'只转换 ASCII 字母、数字、符号及普通/全角空格，不处理半角片假名。换行与其他文字保持不变。',invisible:'检查常见控制字符、零宽字符和特殊空格。部分字符用于正常语言排版或表情；清理是显式操作，不会自动修改原文。'}[this.mode];}},beforeUnmount(){++this.request;},methods:{async run(){const request=++this.request;this.busy=true;this.message='';const input=this.input;try{let output;if(this.mode==='chinese'){const[from,to]=this.direction.split('-');output=await convertChinese(input,from,to);}if(this.mode==='pinyin')output=await chineseToPinyin(input,{toneType:this.tone,initials:this.initials,uppercase:this.uppercase});if(this.mode==='width')output=convertWidth(input,this.widthMode==='full');if(this.mode==='invisible'){this.inspection=inspectInvisible(input,this.includeWhitespace);output=this.inspection.annotated;}if(request===this.request){this.output=output;this.message='处理完成';}}catch(error){if(request===this.request){this.output='';this.message=error.message;}}finally{if(request===this.request)this.busy=false;}},clean(){this.output=cleanInvisible(this.input,{keepWhitespace:this.keepWhitespace,keepEmoji:this.keepEmoji});this.message='已生成清理副本，原文未修改';},clear(){++this.request;this.input='';this.output='';this.inspection=null;this.message='';this.busy=false;},async copy(){try{await navigator.clipboard.writeText(this.output);this.message='已复制结果';}catch{this.message='复制未完成，请选中结果手动复制';}}}};
</script>
<style scoped>.invisible-table{max-height:280px;overflow:auto;}table{width:100%;border-collapse:collapse;}th,td{text-align:left;padding:7px;border:1px solid var(--el-border-color);overflow-wrap:anywhere;}</style>
